<?php

/**
 * @file
 * Helpers to build Noah's Page Builder designs by code. require_once this file from your build scripts.
 *
 * Structure format (see references/data-model.md):
 *   [ {wid, type: "noahs_row", element: {...}, columns: [
 *       {wid, type: "noahs_column", element: {...}, elements: [ {wid, type: "<widget>", element: {...}}, <nested row>… ]}
 *   ]} ]
 * "element" is what the widget form serializes. Every widget starts from its REAL defaults (work/defaults.json,
 * generated by `noahs.sh defaults` from the installed version) and only the paths you pass are changed.
 *
 * Saving a structure does not create its CSS: run `noahs.sh css <entity_type> <id>` afterwards.
 */

use Drupal\Core\Cache\Cache;
use Drupal\media\Entity\Media;

/* ----------------------------------------------------------------------------------------------------------------
 * Core structure helpers.
 * -------------------------------------------------------------------------------------------------------------- */

function noahs_defaults(): array {
  static $defaults = NULL;
  if ($defaults === NULL) {
    $file = dirname(__DIR__) . '/work/defaults.json';
    $defaults = is_file($file) ? json_decode(file_get_contents($file), TRUE) : NULL;
    if (!is_array($defaults)) {
      throw new \RuntimeException('work/defaults.json is missing: run `noahs.sh defaults` first.');
    }
  }
  return $defaults;
}

function noahs_has_widget(string $type): bool {
  return isset(noahs_defaults()[$type]);
}

function noahs_is_pro(): bool {
  return \Drupal::moduleHandler()->moduleExists('noahs_page_builder_pro');
}

function noahs_require_pro(): void {
  if (!noahs_is_pro()) {
    throw new \RuntimeException('This script uses Noahs Pro features but noahs_page_builder_pro is not enabled.');
  }
}

/** Sets a value by dotted path: noahs_set($el, 'css.desktop.default.font.font_size', '18px'). */
function noahs_set(array &$array, string $path, $value): void {
  $ref = &$array;
  foreach (explode('.', $path) as $key) {
    if (!isset($ref[$key]) || !is_array($ref[$key])) {
      $ref[$key] = [];
    }
    $ref = &$ref[$key];
  }
  $ref = $value;
}

function noahs_unset(array &$array, string $path): void {
  $keys = explode('.', $path);
  $last = array_pop($keys);
  $ref = &$array;
  foreach ($keys as $key) {
    if (!isset($ref[$key]) || !is_array($ref[$key])) {
      return;
    }
    $ref = &$ref[$key];
  }
  unset($ref[$last]);
}

/**
 * Stable widget id from a seed: re-running a script gives the same ids (idempotent, same CSS selectors).
 * Use a prefix per design (e.g. "home-", "hdr-", "ftr-") because header, footer and page share one HTML page.
 */
function noahs_wid(string $seed): string {
  return 'n' . substr(md5($seed), 0, 9);
}

/** A widget: real defaults + dotted-path overrides. */
function noahs_widget(string $type, string $seed, array $set = [], array $unset = []): array {
  $defaults = noahs_defaults();
  if (!isset($defaults[$type])) {
    throw new \RuntimeException("Unknown widget '$type' (not installed, or Pro-only on a free site). Run `noahs.sh env`.");
  }
  $element = $defaults[$type];
  foreach ($unset as $path) {
    noahs_unset($element, $path);
  }
  foreach ($set as $path => $value) {
    noahs_set($element, $path, $value);
  }
  return ['wid' => noahs_wid($seed), 'type' => $type, 'element' => $element];
}

/** A column. $widths = [desktop, tablet, mobile], e.g. ['calc(50% - 15px)', '100%', '100%']. */
function noahs_column(string $seed, array $elements, array $widths = ['100%'], array $set = []): array {
  $col = noahs_widget('noahs_column', $seed, $set + noahs_resp('column_width', $widths));
  $col['elements'] = $elements;
  return $col;
}

/** A section (row). Use 'class.section_container' => 'n-container' (boxed) or 'n-container-fluid' (full width). */
function noahs_section(string $seed, array $columns, array $set = []): array {
  $row = noahs_widget('noahs_row', $seed, $set + ['class.section_container' => 'n-container']);
  $row['columns'] = $columns;
  return $row;
}

/**
 * A nested section inside a column. A column placed directly in another column's elements is NOT rendered:
 * always wrap inner columns in a nested row.
 */
function noahs_inner(string $seed, array $columns, array $set = []): array {
  return noahs_section($seed, $columns, $set + [
    'class.section_container' => 'n-container-fluid',
    'css.desktop.default.padding' => noahs_box('padding', '0px', '0px', '0px', '0px'),
  ]);
}

/* ----------------------------------------------------------------------------------------------------------------
 * Value builders for common controls.
 * -------------------------------------------------------------------------------------------------------------- */

/** Responsive values: noahs_resp('padding', [$desktop, $tablet, $mobile]) → css.<bp>.<state>.<path>. NULL skips one. */
function noahs_resp(string $path, array $values, string $state = 'default'): array {
  $out = [];
  foreach (['desktop', 'tablet', 'mobile'] as $i => $bp) {
    if (array_key_exists($i, $values) && $values[$i] !== NULL) {
      $out["css.$bp.$state.$path"] = $values[$i];
    }
  }
  return $out;
}

/**
 * Sub-keys of a noahs_font control: font_family, font_weight, font_size, line_height, letter_spacing,
 * text_transform, font_style, text_decoration, color (+ margin_top/bottom, padding_top/bottom).
 */
function noahs_font(string $control, array $font, string $bp = 'desktop', string $state = 'default'): array {
  $out = [];
  foreach ($font as $k => $v) {
    $out["css.$bp.$state.$control.$k"] = $v;
  }
  return $out;
}

/** padding / margin value: noahs_box('padding', top, right, bottom, left). */
function noahs_box(string $prefix, string $top, string $right, string $bottom, string $left): array {
  return ["{$prefix}_top" => $top, "{$prefix}_right" => $right, "{$prefix}_bottom" => $bottom, "{$prefix}_left" => $left];
}

function noahs_border(string $color, string $top = '1px', string $right = '1px', string $bottom = '1px', string $left = '1px', string $style = 'solid'): array {
  return ['border_color' => $color, 'border_style' => $style, 'border_top_width' => $top, 'border_right_width' => $right, 'border_bottom_width' => $bottom, 'border_left_width' => $left];
}

function noahs_radius(string $r): array {
  return ['border_top_left_radius' => $r, 'border_top_right_radius' => $r, 'border_bottom_right_radius' => $r, 'border_bottom_left_radius' => $r];
}

function noahs_shadow(string $x, string $y, string $blur, string $spread, string $color): array {
  return ['shadow_x' => $x, 'shadow_y' => $y, 'blur' => $blur, 'spread' => $spread, 'color' => $color];
}

/** noahs_url control. A Drupal path ("/shop"), an absolute URL, or "entity:node/12"-style values via entity_id. */
function noahs_url_value(string $url, string $entity_id = ''): array {
  return ['source' => 'custom', 'url' => $url, 'entity_id' => $entity_id, 'text' => $url, 'url_params' => ''];
}

/* ----------------------------------------------------------------------------------------------------------------
 * Images: Noahs image controls store the id of a media entity of type "noahs_image" (not a file id).
 * -------------------------------------------------------------------------------------------------------------- */

/** Copies a local image into public://noahs-build/ and returns a noahs_image media for it (reused by name). */
function noahs_media_from_file(string $path, string $name, string $alt): Media {
  if (!is_file($path)) {
    throw new \RuntimeException("Image not found: $path");
  }
  $storage = \Drupal::entityTypeManager()->getStorage('media');
  $found = $storage->loadByProperties(['bundle' => 'noahs_image', 'name' => $name]);
  if ($found) {
    return reset($found);
  }
  $dir = 'public://noahs-build';
  \Drupal::service('file_system')->prepareDirectory($dir, \Drupal\Core\File\FileSystemInterface::CREATE_DIRECTORY);
  $replace = enum_exists('\Drupal\Core\File\FileExists') ? \Drupal\Core\File\FileExists::Replace : \Drupal\Core\File\FileSystemInterface::EXISTS_REPLACE;
  $file = \Drupal::service('file.repository')->writeData(file_get_contents($path), "$dir/" . basename($path), $replace);
  $file->setPermanent();
  $file->save();
  $media = Media::create(['bundle' => 'noahs_image', 'name' => $name, 'uid' => 1, 'field_media_image' => ['target_id' => $file->id(), 'alt' => $alt]]);
  $media->setPublished()->save();
  return $media;
}

/** Value of a noahs_image control (Image, Card, Card Grid items…). */
function noahs_image_value(Media $media, string $image_style = ''): array {
  $url = \Drupal::service('file_url_generator')->generateString($media->get('field_media_image')->entity->getFileUri());
  return ['fid' => (string) $media->id(), 'thumbnail' => $url, 'media_type' => 'noahs_image', 'url' => $url, 'token_media' => '', 'image_style' => $image_style];
}

/** Value of a noahs_background_image control (section / column / slide backgrounds). Goes under css.<bp>.default.<field>. */
function noahs_background_value(Media $media, string $position = 'center center', string $size = 'cover', string $image_style = ''): array {
  $url = \Drupal::service('file_url_generator')->generateString($media->get('field_media_image')->entity->getFileUri());
  return [
    'background_image' => [
      'fid' => (string) $media->id(), 'thumbnail' => $url, 'url' => $url, 'media_type' => 'noahs_image',
      'background_position' => $position, 'background_repeat' => 'no-repeat', 'background_attachment' => 'scroll', 'background_size' => $size,
    ],
    'token_media' => '', 'image_style' => $image_style, 'background_size_custom' => '', 'background_position_custom' => '',
  ];
}

/* ----------------------------------------------------------------------------------------------------------------
 * Saving designs (free).
 * -------------------------------------------------------------------------------------------------------------- */

/**
 * Creates or updates a node found by its path alias (idempotent). The bundle must be enabled for Noahs
 * (Settings → use_in_ctype), otherwise the design is not rendered.
 */
function noahs_ensure_node(string $alias, string $title, string $type = 'page', string $langcode = 'en'): \Drupal\node\NodeInterface {
  $enabled = array_filter((array) \Drupal::config('noahs_page_builder.settings')->get('use_in_ctype'));
  if (!isset($enabled[$type])) {
    echo "WARNING: node type '$type' is not enabled for Noahs (Settings → use_in_ctype)." . PHP_EOL;
  }
  $path = \Drupal::service('path_alias.repository')->lookupByAlias($alias, $langcode);
  $storage = \Drupal::entityTypeManager()->getStorage('node');
  $node = NULL;
  if ($path && preg_match('#^/node/(\d+)$#', $path['path'], $m)) {
    $node = $storage->load($m[1]);
  }
  if (!$node) {
    $node = $storage->create(['type' => $type, 'langcode' => $langcode, 'uid' => 1, 'path' => ['alias' => $alias]]);
  }
  $node->setTitle($title)->setPublished();
  $node->save();
  return $node;
}

/** Saves a structure for an entity (node, block_content, taxonomy_term, commerce_product), like the editor (no CSS). */
function noahs_save_page(string $entity_type, string|int $id, array $sections, string $langcode = 'en'): void {
  $id = (string) $id;
  $db = \Drupal::database();
  $row = ['settings' => json_encode($sections, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE), 'modified_date' => time()];
  $page_id = $db->select('noahs_page_builder_page', 'd')->fields('d', ['page_id'])
    ->condition('noahs_id', $id)->condition('entity_type', $entity_type)->condition('langcode', $langcode)
    ->execute()->fetchField();
  if ($page_id) {
    $db->update('noahs_page_builder_page')->fields($row)->condition('page_id', $page_id)->execute();
  }
  else {
    $db->insert('noahs_page_builder_page')->fields($row + [
      'noahs_id' => $id, 'entity_id' => $id, 'entity_type' => $entity_type, 'langcode' => $langcode, 'uid' => 1,
    ])->execute();
  }
  Cache::invalidateTags(['rendered', 'noahs_theme_templates', "$entity_type:$id"]);
}

/** Removes a saved design and its CSS file (all languages). */
function noahs_delete_page(string $entity_type, string|int $id): void {
  \Drupal::database()->delete('noahs_page_builder_page')
    ->condition('noahs_id', (string) $id)->condition('entity_type', $entity_type)->execute();
  foreach (glob(\Drupal::service('file_system')->realpath('public://noahs/' . $entity_type) . "/noahs_{$id}_*.css") ?: [] as $f) {
    @unlink($f);
  }
  Cache::invalidateTags(['rendered', "$entity_type:$id"]);
}

/**
 * Reusable content block of type noahs_block_html designed with Noahs (free header/footer pieces, mega menu panels).
 * Found by its description (idempotent). Returns the block_content entity; place it with a block plugin
 * "block_content:<uuid>" in a theme region, or reference it from a menu link (field noahs_megamenu_block).
 */
function noahs_save_block(string $info, array $sections, string $langcode = 'en') {
  $storage = \Drupal::entityTypeManager()->getStorage('block_content');
  $found = $storage->loadByProperties(['info' => $info, 'type' => 'noahs_block_html']);
  $block = $found ? reset($found) : $storage->create(['type' => 'noahs_block_html', 'info' => $info, 'reusable' => TRUE, 'langcode' => $langcode]);
  $block->save();
  noahs_save_page('block_content', $block->id(), $sections, $langcode);
  return $block;
}

/* ----------------------------------------------------------------------------------------------------------------
 * Pro: Theme builder and Display builder. Call noahs_require_pro() first.
 * -------------------------------------------------------------------------------------------------------------- */

/**
 * Saves a Theme builder template: header, footer, noahs_page, a node bundle (blog…), commerce_<product type>,
 * commerce_cart, noahs_login… CSS: `noahs.sh css pro_theme <type>`.
 *
 * @param array|null $page_settings
 *   The template settings form values ("element"), e.g. for a header:
 *   ['class' => ['header_layout' => 'header_sticky'], 'hide_on_scroll_down' => 'on', 'css' => [...]]. NULL keeps the current ones.
 */
function noahs_save_theme(string $type, array $sections, ?array $page_settings = NULL, string $langcode = 'en'): void {
  $db = \Drupal::database();
  $row = ['entity_type' => 'pro_theme', 'settings' => json_encode($sections, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE), 'modified_date' => (string) time()];
  if ($page_settings !== NULL) {
    $row['page_settings'] = json_encode(['page_settings' => ['element' => $page_settings], 'page_fields' => []], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
  }
  $id = $db->select('noahs_page_builder_pro_themes', 't')->fields('t', ['theme_id'])
    ->condition('type', $type)->condition('langcode', $langcode)->execute()->fetchField();
  if ($id) {
    $db->update('noahs_page_builder_pro_themes')->fields($row)->condition('theme_id', $id)->execute();
  }
  else {
    $db->insert('noahs_page_builder_pro_themes')->fields($row + ['type' => $type, 'langcode' => $langcode, 'page_settings' => $row['page_settings'] ?? '{}'])->execute();
  }
  Cache::invalidateTags(['noahs_theme_templates', 'rendered']);
}

/** Removes a Theme builder template row and its CSS. */
function noahs_delete_theme(string $type): void {
  \Drupal::database()->delete('noahs_page_builder_pro_themes')->condition('type', $type)->execute();
  foreach (glob(\Drupal::service('file_system')->realpath('public://noahs/pro_theme') . "/noahs_{$type}_*.css") ?: [] as $f) {
    @unlink($f);
  }
  Cache::invalidateTags(['noahs_theme_templates', 'rendered']);
}

/**
 * Conditions of a Theme builder template (config noahs_page_builder_pro.theme_assignments → templates.<type>).
 * Without an entry the template applies everywhere. Variants (e.g. a landing header) use $variant = TRUE and a
 * higher priority. Conditions: include_paths / exclude_paths / include_routes / exclude_routes (one pattern per
 * line, "*" wildcard, "<front>"), roles[], languages[], bundles[] ("node:blog").
 */
function noahs_theme_conditions(string $type, string $label, string $kind, array $conditions = [], int $priority = 0, bool $variant = FALSE): void {
  $conditions += ['include_paths' => '', 'exclude_paths' => '', 'include_routes' => '', 'exclude_routes' => '', 'roles' => [], 'languages' => [], 'bundles' => []];
  $assignment = [
    'label' => $label, 'kind' => $kind, 'entity_type' => 'pro_theme', 'enabled' => TRUE, 'priority' => $priority,
    'variant' => $variant, 'assignment_version' => 1, 'conditions' => $conditions,
  ];
  if (\Drupal::hasService('noahs_page_builder_pro.theme_template_manager')) {
    \Drupal::service('noahs_page_builder_pro.theme_template_manager')->saveAssignment($type, $assignment);
  }
  else {
    \Drupal::configFactory()->getEditable('noahs_page_builder_pro.theme_assignments')->set("templates.$type", $assignment)->save();
  }
  Cache::invalidateTags(['noahs_theme_templates', 'rendered']);
}

/** Removes the conditions entry of a template type. */
function noahs_theme_conditions_delete(string $type): void {
  $config = \Drupal::configFactory()->getEditable('noahs_page_builder_pro.theme_assignments');
  $config->clear("templates.$type")->save();
  Cache::invalidateTags(['noahs_theme_templates', 'rendered']);
}

/**
 * Saves a Display builder design (entity type + bundle + view mode, e.g. node/blog/teaser). $langcode '' = any.
 * CSS: `noahs.sh css pro_display <entity_type>:<bundle>:<view_mode>`. The view mode must exist.
 */
function noahs_save_design(string $entity_type, string $bundle, string $view_mode, array $sections, string $langcode = 'en'): int {
  $db = \Drupal::database();
  $now = date('c');
  $json = json_encode($sections, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
  $id = $db->select('noahs_page_builder_pro_designs', 'd')->fields('d', ['id'])
    ->condition('entity_type', $entity_type)->condition('entity', $bundle)->condition('display', $view_mode)
    ->condition('langcode', $langcode)->execute()->fetchField();
  if ($id) {
    $db->update('noahs_page_builder_pro_designs')->fields(['settings' => $json, 'modified' => $now])->condition('id', $id)->execute();
  }
  else {
    $id = $db->insert('noahs_page_builder_pro_designs')->fields([
      'entity' => $bundle, 'entity_type' => $entity_type, 'display' => $view_mode, 'langcode' => $langcode,
      'settings' => $json, 'page_settings' => '', 'created' => $now, 'modified' => $now,
    ])->execute();
  }
  Cache::invalidateTags(['rendered', $entity_type . '_view']);
  return (int) $id;
}

/* ----------------------------------------------------------------------------------------------------------------
 * Pro "Extras": motion attributes. They return dotted paths for noahs_widget(…, $set). Attributes only (no CSS):
 * the Pro front-end JS reads data-noahs-motion-* from the widget wrapper.
 * -------------------------------------------------------------------------------------------------------------- */

/** Entrance: fade, fade-up, fade-down, fade-left, fade-right, zoom-in, zoom-out, flip-up. Devices: all | desktop | no-mobile. */
function noahs_motion_enter(string $effect = 'fade-up', int $duration = 700, int $delay = 0, string $devices = 'all'): array {
  return ['attribute.motion_enter' => $effect, 'attribute.motion_duration' => (string) $duration, 'attribute.motion_delay' => (string) $delay, 'attribute.motion_devices' => $devices];
}

/** Cascade: animates the direct children of a row or column one after another. Order: forward | reverse | center. */
function noahs_motion_cascade(string $effect = 'fade-up', int $gap = 120, int $duration = 600, string $order = 'forward'): array {
  return ['attribute.motion_cascade' => $effect, 'attribute.motion_cascade_gap' => (string) $gap, 'attribute.motion_cascade_duration' => (string) $duration, 'attribute.motion_cascade_order' => $order];
}

/** Scroll-linked: rise, drift, zoom, reveal, depth (parallax), soft-reveal, fade-out, rotate-in. Smoothing 0 = native, 1:1. */
function noahs_motion_scroll(string $preset = 'depth', int $intensity = 100, int $smoothing = 0, string $devices = 'all'): array {
  return ['attribute.motion_scroll' => $preset, 'attribute.motion_intensity' => (string) $intensity, 'attribute.motion_smoothing' => (string) $smoothing, 'attribute.motion_scroll_devices' => $devices];
}

/** Gentle floating drift (any widget except row/column). */
function noahs_motion_float(int $distance = 10, int $duration = 14): array {
  return ['attribute.motion_float' => 'on', 'attribute.motion_float_distance' => (string) $distance, 'attribute.motion_float_duration' => (string) $duration];
}

/** Hero scroll scene on a row: the section shrinks and rounds while the next one is revealed. */
function noahs_motion_hero_shrink(float $scale = 0.9, int $radius = 28, int $smoothing = 0): array {
  return ['attribute.motion_hero' => 'shrink', 'attribute.motion_hero_scale' => (string) $scale, 'attribute.motion_hero_radius' => (string) $radius, 'attribute.motion_hero_smoothing' => (string) $smoothing];
}

/** Hover transform (CSS, Transform control): e.g. ['scale' => '1.03', 'translate_y' => '-4px']. */
function noahs_hover_transform(array $transform): array {
  return ['css.desktop.hover.noahs_element_transform' => $transform];
}
